changeSet.sql:
-- REGLEMENTS FOURNISSEUR (ReglementFournisseurSearchCriteria) : tri date_reglement DESC ou id DESC
CREATE INDEX IF NOT EXISTS idx_regl_frn_pdv_date      ON reglements_fournisseur (point_de_vente_id, date_reglement DESC);
CREATE INDEX IF NOT EXISTS idx_regl_frn_pdv_id        ON reglements_fournisseur (point_de_vente_id, id DESC);
CREATE INDEX IF NOT EXISTS idx_regl_frn_facture       ON reglements_fournisseur (facture_achat_id);
CREATE INDEX IF NOT EXISTS idx_regl_frn_pdv_mode      ON reglements_fournisseur (point_de_vente_id, mode_paiement, date_reglement DESC);
CREATE INDEX IF NOT EXISTS idx_regl_frn_pdv_echeance  ON reglements_fournisseur (point_de_vente_id, date_echeance);

-- FACTURES ACHAT : filtres fournisseur et tenant pour les jointures
CREATE INDEX IF NOT EXISTS idx_factures_achat_fournisseur ON factures_achat (fournisseur_id);
CREATE INDEX IF NOT EXISTS idx_factures_achat_pdv_date    ON factures_achat (point_de_vente_id, date_facture DESC);

CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- Règlements fournisseur : recherche textuelle insensible à la casse
CREATE INDEX IF NOT EXISTS idx_trgm_regl_frn_numero ON reglements_fournisseur USING gin (lower(numero_reglement) gin_trgm_ops);
CREATE INDEX IF NOT EXISTS idx_trgm_regl_frn_ref    ON reglements_fournisseur USING gin (lower(reference_paiement) gin_trgm_ops);
CREATE INDEX IF NOT EXISTS idx_trgm_regl_frn_cheque ON reglements_fournisseur USING gin (lower(numero_cheque) gin_trgm_ops);
CREATE INDEX IF NOT EXISTS idx_trgm_regl_frn_banque ON reglements_fournisseur USING gin (lower(nom_banque) gin_trgm_ops);

-- Factures achat : recherche numero_facture
CREATE INDEX IF NOT EXISTS idx_trgm_fact_achat_num  ON factures_achat         USING gin (lower(numero_facture) gin_trgm_ops);
